#!/usr/bin/env node
/**
 * Turns db/migrations/*.sql into db/migrations.generated.ts.
 *
 * Why: the app applies its own migrations (lib/db/migrate.ts), including into
 * the in-memory database a preview or a test runs on, and on hosts that have
 * no filesystem to read a folder from. So the SQL travels inside the bundle,
 * as a module, rather than beside it as files.
 *
 * Run by `npm run db:generate` straight after drizzle-kit writes the folder.
 * `--check` exits 1 if the generated file is stale, which is what the unit
 * test and CI use.
 */
import { createHash } from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const dir = "db/migrations";
const out = "db/migrations.generated.ts";

const journal = JSON.parse(
  readFileSync(join(dir, "meta", "_journal.json"), "utf8"),
);

const entries = [...journal.entries]
  .sort((a, b) => a.idx - b.idx)
  .map((entry) => {
    const sql = readFileSync(join(dir, `${entry.tag}.sql`), "utf8");
    return {
      tag: entry.tag,
      hash: createHash("sha256").update(sql).digest("hex").slice(0, 16),
      statements: sql
        .split("--> statement-breakpoint")
        .map((part) => part.trim())
        .filter((part) => part !== ""),
    };
  });

const body = `/**
 * GENERATED by scripts/embed-migrations.mjs from db/migrations. Do not edit.
 * Change db/schema, then run \`npm run db:generate\`.
 */

export type Migration = {
  readonly tag: string;
  /** First 16 hex characters of the SHA-256 of the SQL file. */
  readonly hash: string;
  readonly statements: readonly string[];
};

export const MIGRATIONS: readonly Migration[] = ${JSON.stringify(entries, null, 2)};
`;

if (process.argv.includes("--check")) {
  let current = "";
  try {
    current = readFileSync(out, "utf8");
  } catch {
    current = "";
  }
  if (current !== body) {
    console.error(
      `${out} is out of date with ${dir}. Run: npm run db:generate`,
    );
    process.exit(1);
  }
  console.log(`${out} is up to date (${String(entries.length)} migration(s)).`);
} else {
  writeFileSync(out, body);
  console.log(`wrote ${out} (${String(entries.length)} migration(s)).`);
}
